/**
 * Third-Party Ticket Integration Flow
 *
 * This flow handles inbound requests from third-party IT ticket tracking systems:
 * 1. Triggers when an inbound email/request is received from external system
 * 2. Attempts to create an incident with the request body as short description
 * 3. Fires an event upon successful incident creation
 * 4. Logs error details if incident creation fails
 *
 * Uses try-catch pattern for error handling:
 * - Try: Create incident and fire event
 * - Catch: Log the error with incident details
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const thirdPartyTicketIntegrationFlow = Flow(
    {
        $id: Now.ID['third_party_ticket_integration_flow'],
        name: 'Third-Party Ticket Integration Flow',
        description: 'Handles inbound requests from third-party IT ticket tracking systems with error handling',
    },
    wfa.trigger(
        trigger.application.inboundEmail,
        { $id: Now.ID['third_party_request_trigger'] },
        {
            email_conditions: 'subjectLIKEexternal^ORsubjectLIKEthird-party^ORsubjectLIKEticket',
            target_table: 'incident',
            order: 100,
            stop_condition_evaluation: false,
        }
    ),
    (params) => {
        // Step 1: Log receipt of inbound request
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_request_received'],
                annotation: 'Log inbound request from third-party system',
            },
            {
                log_level: 'info',
                log_message: `Received inbound request from third-party system. From: ${wfa.dataPill(params.trigger.from_address, 'string')}, Subject: ${wfa.dataPill(params.trigger.subject, 'string')}`,
            }
        )

        // Step 2: Extract request body for incident creation
        const requestBody = wfa.action(
            action.core.getLatestResponseTextFromEmail,
            {
                $id: Now.ID['extract_request_body'],
                annotation: 'Extract the request body from email',
            },
            {
                email_record: `${wfa.dataPill(params.trigger.inbound_email, 'records')}`,
            }
        )

        // Step 3: Try-Catch Block - Attempt to create incident
        // Try Block: Create incident with request body
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(requestBody.latest_response_text, 'string')}ISNOTEMPTY`,
                annotation: 'Verify request body is not empty before creating incident',
                $id: Now.ID['check_request_body_exists'],
            },
            () => {
                // Try: Create incident with request body as short description
                const newIncident = wfa.action(
                    action.core.createRecord,
                    {
                        $id: Now.ID['create_incident_from_request'],
                        annotation: 'Create incident from third-party request',
                    },
                    {
                        table_name: 'incident',
                        values: TemplateValue({
                            short_description: `${wfa.dataPill(requestBody.latest_response_text, 'string')}`,
                            description: `Third-party ticket received from: ${wfa.dataPill(params.trigger.from_address, 'string')}\n\nOriginal Subject: ${wfa.dataPill(params.trigger.subject, 'string')}\n\nRequest Body:\n${wfa.dataPill(requestBody.latest_response_text, 'string')}`,
                            priority: 3,
                            urgency: 3,
                            state: 1,
                            category: 'inquiry',
                            contact_type: 'email',
                            caller_id: `${wfa.dataPill(params.trigger.from_address, 'string')}`,
                        }),
                    }
                )

                // Check if incident was created successfully
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(newIncident.record, 'reference')}ISNOTEMPTY`,
                        annotation: 'Verify incident was created successfully',
                        $id: Now.ID['verify_incident_created'],
                    },
                    () => {
                        // Success: Log successful creation
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['log_incident_created_success'],
                                annotation: 'Log successful incident creation',
                            },
                            {
                                log_level: 'info',
                                log_message: `Incident successfully created from third-party request: ${wfa.dataPill(newIncident.record, 'reference')}`,
                            }
                        )

                        // Fire event for successful incident creation
                        wfa.action(
                            action.core.fireEvent,
                            {
                                $id: Now.ID['fire_incident_created_event'],
                                annotation: 'Fire event for third-party incident creation',
                            },
                            {
                                event_name: 'third_party.incident.created',
                                table: 'incident',
                                record: `${wfa.dataPill(newIncident.record, 'reference')}`,
                                parm1: `${wfa.dataPill(params.trigger.from_address, 'string')}`,
                                parm2: `${wfa.dataPill(params.trigger.subject, 'string')}`,
                            }
                        )

                        // Associate the inbound email with the created incident
                        wfa.action(
                            action.core.associateRecordToEmail,
                            {
                                $id: Now.ID['associate_email_to_incident'],
                                annotation: 'Link inbound email to created incident',
                            },
                            {
                                email_record: `${wfa.dataPill(params.trigger.inbound_email, 'records')}`,
                                target_record: `${wfa.dataPill(newIncident.record, 'reference')}`,
                            }
                        )

                        // Send confirmation notification back to sender
                        wfa.action(
                            action.core.sendNotification,
                            {
                                $id: Now.ID['send_confirmation_notification'],
                                annotation: 'Send confirmation notification to third-party system',
                            },
                            {
                                table_name: 'incident',
                                record: `${wfa.dataPill(newIncident.record, 'reference')}`,
                                notification: 'third_party_incident_created_confirmation_notification',
                            }
                        )
                    }
                )

                // Catch Block: Handle incident creation failure
                wfa.flowLogic.else(
                    {
                        annotation: 'Handle incident creation failure (Catch block)',
                        $id: Now.ID['catch_incident_creation_error'],
                    },
                    () => {
                        // Log the error with incident details
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['log_incident_creation_error'],
                                annotation: 'Log incident creation error with details',
                            },
                            {
                                log_level: 'error',
                                log_message: `ERROR: Failed to create incident from third-party request. Short description attempted: ${wfa.dataPill(requestBody.latest_response_text, 'string')}. Source: ${wfa.dataPill(params.trigger.from_address, 'string')}. Subject: ${wfa.dataPill(params.trigger.subject, 'string')}`,
                            }
                        )

                        // Send failure notification to system administrators
                        wfa.action(
                            action.core.sendNotification,
                            {
                                $id: Now.ID['send_error_notification'],
                                annotation: 'Send error notification to administrators',
                            },
                            {
                                table_name: 'sys_email',
                                record: `${wfa.dataPill(params.trigger.inbound_email, 'records')}`,
                                notification: 'third_party_integration_error_notification',
                            }
                        )

                        // Create a manual review task for failed incident
                        wfa.action(
                            action.core.createTask,
                            {
                                $id: Now.ID['create_manual_review_task'],
                                annotation: 'Create manual review task for failed incident creation',
                            },
                            {
                                task_table: 'task',
                                field_values: TemplateValue({
                                    short_description: `Manual Review Required: Failed Third-Party Incident Creation`,
                                    description: `Failed to create incident from third-party system.\n\nAttempted Short Description: ${wfa.dataPill(requestBody.latest_response_text, 'string')}\n\nSource: ${wfa.dataPill(params.trigger.from_address, 'string')}\nSubject: ${wfa.dataPill(params.trigger.subject, 'string')}\n\nPlease review the inbound email and create the incident manually if needed.`,
                                    priority: 2,
                                    urgency: 2,
                                    state: 1,
                                }),
                            }
                        )
                    }
                )
            }
        )

        // Handle empty request body case
        wfa.flowLogic.else(
            {
                annotation: 'Handle empty request body scenario',
                $id: Now.ID['handle_empty_request_body'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_empty_request_body'],
                        annotation: 'Log empty request body error',
                    },
                    {
                        log_level: 'error',
                        log_message: `ERROR: Received third-party request with empty body. From: ${wfa.dataPill(params.trigger.from_address, 'string')}, Subject: ${wfa.dataPill(params.trigger.subject, 'string')}. Unable to create incident.`,
                    }
                )
            }
        )
    }
)
